window.futvizVista("corte-vs-cobertura","<div class=\"rx-mount\" data-rx=\"scatter\" data-rx-id=\"corte-vs-cobertura\" style=\"min-height:520px\"></div><script>(window.futvizVistas=window.futvizVistas||{})[\"corte-vs-cobertura\"]={\"id\":\"corte-vs-cobertura\",\"titulo\":\"Corte vs. Cobertura\",\"bajada\":\"Arriba, los defensas que van al choque (corte); a la derecha, los que leen el pase (cobertura).\",\"pregunta\":\"\u00bfQui\u00e9n va al choque y qui\u00e9n lee el juego?\",\"tabla\":\"jugadores\",\"entidad\":\"jugadores\",\"x\":{\"col\":\"pct_cover\",\"label\":\"Cobertura: percentil de intercepciones por 90'\",\"corto\":\"Cobertura\",\"dec\":0},\"y\":{\"col\":\"pct_stopper\",\"label\":\"Corte: percentil de entradas ganadas y faltas por 90'\",\"corto\":\"Corte\",\"dec\":0},\"referencia\":{\"tipo\":\"promedios\",\"fijo\":{\"x\":70,\"y\":70},\"cuadrantes\":{\"tr\":\"Chocan y leen el pase\",\"tl\":\"Van m\u00e1s al choque\",\"br\":\"Leen m\u00e1s el pase\",\"bl\":\"Sin destacar en ninguna\"}},\"requiere\":[\"pct_cover\",\"pct_stopper\"],\"subtitulo\":\"Defensas con \u2265{min} min \u00b7 {temporada}\",\"filtros\":{\"posicion\":false,\"nivel\":true,\"sub21\":true},\"metricas\":[{\"id\":\"x\",\"etiqueta\":\"Cobertura\",\"ayuda\":\"Ordenados por Cobertura: percentil de intercepciones por 90'\"},{\"id\":\"y\",\"etiqueta\":\"Corte\",\"ayuda\":\"Ordenados por Corte: percentil de entradas ganadas y faltas por 90'\"}],\"queMirar\":\"Ubica a cada defensa frente a los de su misma temporada, en percentiles de 0 a 100. El corte, en el eje vertical, promedia dos percentiles, entradas ganadas y faltas por 90 minutos, y refleja qu\u00e9 tanto va al choque.\\nLa cobertura, en el horizontal, es el percentil de intercepciones por 90 minutos y refleja qu\u00e9 tanto lee el pase y se anticipa. Las l\u00edneas est\u00e1n en el percentil 70, as\u00ed que quien las supera destaca en esa faceta.\",\"insight\":\"cover_stopper\",\"fuente\":\"FBref\",\"colorPor\":[\"liga\"],\"nota\":\"Sin despejes, bloqueos ni duelos a\u00e9reos en los datos.\",\"minimoPor90\":true};</script>");